#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_refComp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_refComp(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_rows;
uniform float amzp_cols;
uniform float amzp_gap;
uniform float amzp_backMode;
layout(color) uniform half4 amzp_backCol;
uniform float amzp_g1;
uniform float amzp_g2;
uniform float amzp_gAngle;
uniform float amzp_noiseScale;
uniform float amzp_waveCount;
uniform float amzp_seed;
uniform float amzp_xSrc;
uniform float amzp_xMul;
uniform float amzp_xOff;
uniform float amzp_ySrc;
uniform float amzp_yMul;
uniform float amzp_yOff;
uniform float amzp_zSrc;
uniform float amzp_zMul;
uniform float amzp_zOff;
uniform float amzp_rxSrc;
uniform float amzp_rxMul;
uniform float amzp_rxOff;
uniform float amzp_rySrc;
uniform float amzp_ryMul;
uniform float amzp_ryOff;
uniform float amzp_rzSrc;
uniform float amzp_rzMul;
uniform float amzp_rzOff;
uniform float amzp_sxSrc;
uniform float amzp_sxMul;
uniform float amzp_sxOff;
uniform float amzp_sySrc;
uniform float amzp_syMul;
uniform float amzp_syOff;
uniform float amzp_persp;
uniform float amzp_lightAngle;
uniform float amzp_lightInt;
uniform float amzp_ambient;
uniform float amzp_specular;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * (amzp_aSpeed * 0.5) : amzp_progress; }
    float h21(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 17.13) * 43758.5453123); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), f.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
    float2 W; float2 G; float2 CS; float2 HS;
    float gradV(int ty, float2 uv) {
        float2 d = advRot(float2(1.0, 0.0), radians(amzp_gAngle));
        if (ty == 0) return luma(layerAt(uv).rgb);
        if (ty == 1) return luma(amzTexture(1, clamp(l2s(uv), 0.0, 1.0)).rgb);
        if (ty == 2) return clamp(dot((uv - 0.5) * W, d) / max(abs(d.x) * W.x + abs(d.y) * W.y, 1.0) + 0.5, 0.0, 1.0);
        if (ty == 3) return clamp(length((uv - 0.5) * W) / max(0.5 * length(W), 1.0), 0.0, 1.0);
        float t = TT();
        if (ty == 4) {
            float2 p = uv * G / max(amzp_noiseScale, 0.1);
            return clamp(mix(vn(p + float2(t * 0.9, t * 0.55)), vn(p * 2.1 + float2(-t * 0.7, t * 1.1)), 0.35) * 1.15 - 0.075, 0.0, 1.0);
        }
        return 0.5 + 0.5 * sin((dot(uv - 0.5, d) * amzp_waveCount + t) * 6.28318531);
    }
    float pick(int s, float a, float b, float r) { return s == 1 ? a : (s == 2 ? b : (s == 3 ? r : 0.0)); }
    float3 rotX(float3 v, float a) { float c = cos(a), s = sin(a); return float3(v.x, c * v.y - s * v.z, s * v.y + c * v.z); }
    float3 rotY(float3 v, float a) { float c = cos(a), s = sin(a); return float3(c * v.x + s * v.z, v.y, -s * v.x + c * v.z); }
    float3 rotZ(float3 v, float a) { float c = cos(a), s = sin(a); return float3(c * v.x - s * v.y, s * v.x + c * v.y, v.z); }
    float3 rotF(float3 v, float3 r) { return rotZ(rotY(rotX(v, r.x), r.y), r.z); }
    float3 rotI(float3 v, float3 r) { return rotX(rotY(rotZ(v, -r.z), -r.y), -r.x); }
    void amzRender() {
        W = layer;
        float ps = pxs();
        G = float2(max(floor(amzp_cols + 0.5), 1.0), max(floor(amzp_rows + 0.5), 1.0));
        CS = W / G;
        HS = 0.5 * CS * (1.0 - clamp(amzp_gap, 0.0, 0.95));
        float2 P = (amzLayerNorm() - 0.5) * W;
        float D = 2.0 * max(W.x, W.y) / max(amzp_persp, 0.05);
        float3 O = float3(0.0, 0.0, D);
        float3 dr = normalize(float3(P, -D));
        float zx = (int(amzp_zSrc) > 0 ? abs(amzp_zMul) : 0.0) + abs(amzp_zOff);
        float xyS = (int(amzp_xSrc) > 0 ? abs(amzp_xMul) : 0.0) + abs(amzp_xOff) + (int(amzp_ySrc) > 0 ? abs(amzp_yMul) : 0.0) + abs(amzp_yOff);
        float smax = max(max((int(amzp_sxSrc) > 0 ? abs(amzp_sxMul) : 0.0) + abs(amzp_sxOff), (int(amzp_sySrc) > 0 ? abs(amzp_syMul) : 0.0) + abs(amzp_syOff)), 0.01);
        float hd = length(HS) * smax;
        float zTop = zx * ps + hd, zBot = -zx * ps - hd;
        float q = floor(clamp(amzp_quality, 1.0, 4.0) + 0.5);
        float Mmax = q < 1.5 ? 3.0 : (q < 2.5 ? 6.0 : (q < 3.5 ? 10.0 : 16.0));
        float Kmax = q < 1.5 ? 1.0 : (q < 3.5 ? 2.0 : 3.0);
        float cmin = min(CS.x, CS.y);
        float KW = clamp(1.0 + ceil((xyS * ps + hd * max(smax - 1.0, 0.0)) / cmin), 1.0, Kmax);
        float tTop = (D - zTop) / max(-dr.z, 1e-4), tBot = (D - zBot) / max(-dr.z, 1e-4);
        float shift = length(dr.xy) * (tBot - max(tTop, 0.0));
        float M = clamp(ceil(shift / cmin) + 1.0, 1.0, Mmax);
        float bestT = 1e9;
        float4 bestCol = float4(0.0);
        float3 bestN = float3(0.0, 0.0, 1.0);
        for (int k = 0; k < 16; k++) {
            float fk = float(k);
            if (fk >= M) break;
            float tk = M > 1.0 ? mix(max(tTop, 0.0), tBot, fk / (M - 1.0)) : D / max(-dr.z, 1e-4);
            if (tk > bestT + 2.0 * hd) break;
            float3 X = O + dr * tk;
            float2 cc = floor((X.xy + 0.5 * W) / CS);
            for (int dy = -3; dy <= 3; dy++) {
                for (int dx = -3; dx <= 3; dx++) {
                    if (abs(float(dx)) > KW || abs(float(dy)) > KW) continue;
                    float2 cell = cc + float2(float(dx), float(dy));
                    if (cell.x < 0.0 || cell.y < 0.0 || cell.x >= G.x || cell.y >= G.y) continue;
                    float2 cuv = (cell + 0.5) / G;
                    float2 c0 = (cuv - 0.5) * W;
                    float a1 = gradV(int(amzp_g1), cuv), a2 = gradV(int(amzp_g2), cuv), rr = h21(cell + 3.7);
                    float3 C = float3(c0 + float2(pick(int(amzp_xSrc), a1, a2, rr) * amzp_xMul + amzp_xOff, -(pick(int(amzp_ySrc), a1, a2, rr) * amzp_yMul + amzp_yOff)) * ps,
                                  (pick(int(amzp_zSrc), a1, a2, rr) * amzp_zMul + amzp_zOff) * ps);
                    float3 Rt = radians(float3(pick(int(amzp_rxSrc), a1, a2, rr) * amzp_rxMul + amzp_rxOff, pick(int(amzp_rySrc), a1, a2, rr) * amzp_ryMul + amzp_ryOff, -(pick(int(amzp_rzSrc), a1, a2, rr) * amzp_rzMul + amzp_rzOff)));
                    float2 Sc = float2(pick(int(amzp_sxSrc), a1, a2, rr) * amzp_sxMul + amzp_sxOff, pick(int(amzp_sySrc), a1, a2, rr) * amzp_syMul + amzp_syOff);
                    if (abs(Sc.x) < 1e-3 || abs(Sc.y) < 1e-3) continue;
                    float3 o = rotI(O - C, Rt);
                    float3 d = rotI(dr, Rt);
                    if (abs(d.z) < 1e-5) continue;
                    float t = -o.z / d.z;
                    if (t <= 0.0 || t >= bestT) continue;
                    float2 lp = o.xy + d.xy * t;
                    float2 lim = HS * abs(Sc);
                    if (abs(lp.x) > lim.x || abs(lp.y) > lim.y) continue;
                    bool front = d.z < 0.0;
                    float2 tp = lp / Sc;
                    float4 col;
                    if (front) col = layerAt((c0 + tp) / W + 0.5);
                    else {
                        float4 m = layerAt((c0 + float2(-tp.x, tp.y)) / W + 0.5);
                        col = int(amzp_backMode) == 1 ? float4(amzp_backCol.rgb, 1.0) * m.a : m;
                    }
                    if (col.a < 0.002) continue;
                    float2 e = (lim - abs(lp)) / max(1.0, 0.0001);
                    col *= clamp(min(e.x, e.y), 0.0, 1.0);
                    bestT = t; bestCol = col;
                    bestN = rotF(float3(0.0, 0.0, front ? 1.0 : -1.0), Rt);
                }
            }
        }
        float4 R = float4(0.0);
        if (bestT < 1e8) {
            float la = radians(amzp_lightAngle);
            float3 L = normalize(float3(cos(la), sin(la), 1.2));
            float3 N = bestN;
            float dif = max(dot(N, L), 0.0);
            float flat0 = L.z;
            float sp = pow(max(dot(reflect(-L, N), -dr), 0.0), 30.0);
            float3 base = bestCol.rgb / max(bestCol.a, 0.0001);
            float sh = amzp_ambient + (1.0 - amzp_ambient) * dif / max(flat0, 0.1);
            float3 c = base * mix(1.0, sh, clamp(amzp_lightInt, 0.0, 3.0)) + float3(sp * amzp_specular);
            R = float4(clamp(c, 0.0, 1.0) * bestCol.a, bestCol.a);
        }
        amzOutput = R;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
